{
  "pipeline_id": "somatic-variant-calling",
  "name": "Somatic Variant Calling (Tumor/Normal)",
  "description": "Somatic SNV and indel discovery from matched tumor-normal paired FASTQ files using GATK Mutect2. Aligns both samples independently with BWA-MEM (with read groups, which Mutect2 requires to identify the normal), coordinate-sorts and marks duplicates, then calls somatic variants in tumor-normal paired mode so germline variants present in both samples are excluded. Returns an unannotated VCF: variant consequence annotation is a separate step, since ANNOVAR is licence-gated and not installed.",
  "estimated_duration": "6-12 hours",
  "inputs": [
    {
      "name": "tumorFastqR1",
      "type": "file",
      "required": true,
      "description": "Tumor sample Read 1 FASTQ (.fastq.gz)"
    },
    {
      "name": "tumorFastqR2",
      "type": "file",
      "required": true,
      "description": "Tumor sample Read 2 FASTQ (.fastq.gz)"
    },
    {
      "name": "normalFastqR1",
      "type": "file",
      "required": true,
      "description": "Normal/germline sample Read 1 FASTQ (.fastq.gz)"
    },
    {
      "name": "normalFastqR2",
      "type": "file",
      "required": true,
      "description": "Normal/germline sample Read 2 FASTQ (.fastq.gz)"
    },
    {
      "name": "referenceGenome",
      "type": "string",
      "required": false,
      "default": "references/GRCh38/hg38.fa",
      "description": "Reference genome FASTA"
    },
    {
      "name": "sampleName",
      "type": "string",
      "required": false,
      "default": "tumor_normal",
      "description": "Sample/patient identifier"
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "bwa",
      "description": "Align tumor reads to reference genome"
    },
    {
      "step": 2,
      "tool": "bwa",
      "description": "Align normal reads to reference genome (runs in parallel with tumor alignment)"
    },
    {
      "step": 3,
      "tool": "samtools",
      "description": "Coordinate-sort the tumor BAM (MarkDuplicates requires it)",
      "after": [
        "step1_align_tumor"
      ]
    },
    {
      "step": 4,
      "tool": "samtools",
      "description": "Coordinate-sort the normal BAM (MarkDuplicates requires it)",
      "after": [
        "step1_align_normal"
      ]
    },
    {
      "step": 5,
      "tool": "picard",
      "description": "Mark duplicates in the sorted tumor BAM",
      "after": [
        "step1b_sort_tumor"
      ]
    },
    {
      "step": 6,
      "tool": "picard",
      "description": "Mark duplicates in the sorted normal BAM",
      "after": [
        "step1b_sort_normal"
      ]
    },
    {
      "step": 7,
      "tool": "gatk",
      "description": "Somatic variant calling with Mutect2 in tumor-normal paired mode",
      "after": [
        "step2_markdup_tumor",
        "step2_markdup_normal"
      ]
    }
  ]
}

